// Prompt-template byte-exact match against Python golden.
//
// Fixtures at test/fixtures/prompts/ were generated by
// /Users/kham/Documents/code/benchmarks/cache/_capture_prompt_fixtures.py.
// The TS buildPrompts() must produce byte-identical strings for each
// (task, mode, nonce) combination — cache-prefix matching across impls
// depends on this.

import { readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { buildPrompts } from '../prompts.js';
import { Task } from '../types.js';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const FIXTURES = path.resolve(HERE, '../../../test/fixtures/prompts');

interface PromptFixture {
  task_id: string;
  task_repo: string;
  task_base_commit: string;
  task_problem_statement: string;
  case_label: string;
  agent_mode: boolean;
  nonce: string | null;
  expected_prompts: string[];
}

function loadFixtures(): PromptFixture[] {
  return readdirSync(FIXTURES)
    .filter(name => name.endsWith('.json') && name !== 'MANIFEST.json')
    .sort()
    .map(name => JSON.parse(readFileSync(path.join(FIXTURES, name), 'utf8')));
}

const fixtures = loadFixtures();

describe('prompts: buildPrompts matches Python byte-for-byte', () => {
  for (const fx of fixtures) {
    it(`${fx.case_label}: produces ${fx.expected_prompts.length} prompt(s)`, () => {
      const task: Task = {
        instance_id: fx.task_id,
        repo: fx.task_repo,
        base_commit: fx.task_base_commit,
        problem_statement: fx.task_problem_statement,
      };
      const result = buildPrompts(task, {
        nonce: fx.nonce,
        agentMode: fx.agent_mode,
      });

      expect(result).toHaveLength(fx.expected_prompts.length);
      // Byte-exact match on each prompt. Use eq, not deep-eq, to surface
      // any whitespace / encoding drift immediately.
      for (let i = 0; i < result.length; i++) {
        expect(result[i]).toBe(fx.expected_prompts[i]);
      }
    });
  }
});

describe('prompts: nonce prepend behavior', () => {
  const dummyTask: Task = {
    instance_id: 'demo',
    repo: 'owner/repo',
    base_commit: 'deadbeef',
    problem_statement: 'do the thing',
  };

  it('no nonce → no [trial:] marker on first prompt', () => {
    const r = buildPrompts(dummyTask, {});
    expect(r[0].startsWith('[trial:')).toBe(false);
  });

  it('with nonce → first prompt starts with [trial: <nonce>]', () => {
    const r = buildPrompts(dummyTask, { nonce: 'xyz' });
    expect(r[0].startsWith('[trial: xyz]\n\n')).toBe(true);
  });

  it('nonce applies only to the first prompt, not follow-ups', () => {
    const r = buildPrompts(dummyTask, { nonce: 'xyz' });
    for (let i = 1; i < r.length; i++) {
      expect(r[i].startsWith('[trial:')).toBe(false);
    }
  });

  it('agent mode returns exactly one prompt', () => {
    const r = buildPrompts(dummyTask, { agentMode: true, nonce: 'abc' });
    expect(r).toHaveLength(1);
    expect(r[0].startsWith('[trial: abc]\n\n')).toBe(true);
  });
});
